#!/usr/bin/env node
"use strict";

const http = require("http");

const port = Number(process.env.TASKER_PORT || process.env.PORT || 9556);
const token = String(process.env.TASKER_ACTOR_TOKEN || "");
let input = Buffer.alloc(0);

function taskerRequest(method, pathname, body) {
  return new Promise((resolve, reject) => {
    const raw = body == null ? null : JSON.stringify(body);
    const req = http.request({
      hostname: "127.0.0.1",
      port,
      path: pathname,
      method,
      headers: {
        Authorization: `Bearer ${token}`,
        ...(raw == null ? {} : {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(raw),
        }),
      },
    }, (res) => {
      const chunks = [];
      res.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
      res.on("end", () => {
        const text = Buffer.concat(chunks).toString("utf8");
        let payload = null;
        try { payload = text ? JSON.parse(text) : null; }
        catch { payload = { error: text || `Tasker returned HTTP ${res.statusCode}` }; }
        if (res.statusCode >= 200 && res.statusCode < 300) resolve(payload);
        else {
          const error = new Error((payload && payload.error) || `Tasker returned HTTP ${res.statusCode}`);
          error.code = payload && payload.code;
          error.status = res.statusCode;
          reject(error);
        }
      });
    });
    req.setTimeout(30000, () => req.destroy(new Error("Tasker tool request timed out")));
    req.on("error", reject);
    req.end(raw || undefined);
  });
}

function send(message) {
  process.stdout.write(`${JSON.stringify(message)}\n`);
}

function result(id, value) {
  send({ jsonrpc: "2.0", id, result: value });
}

function failure(id, code, message, data) {
  send({ jsonrpc: "2.0", id, error: { code, message, ...(data ? { data } : {}) } });
}

async function handle(message) {
  if (!message || message.jsonrpc !== "2.0") return;
  const { id, method, params = {} } = message;
  if (method === "notifications/initialized" || method === "notifications/cancelled") return;
  try {
    if (method === "initialize") {
      return result(id, {
        protocolVersion: params.protocolVersion || "2025-06-18",
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: "tasker", version: "1.0.0" },
      });
    }
    if (method === "ping") return result(id, {});
    if (method === "tools/list") {
      const response = await taskerRequest("GET", "/agent/tools");
      return result(id, { tools: response.tools || [] });
    }
    if (method === "tools/call") {
      const response = await taskerRequest("POST", "/agent/tools/call", {
        name: params.name,
        arguments: params.arguments || {},
      });
      const value = response.result == null ? {} : response.result;
      return result(id, {
        content: [{ type: "text", text: JSON.stringify(value, null, 2) }],
        structuredContent: value,
        isError: false,
      });
    }
    return failure(id, -32601, `Method not found: ${method}`);
  } catch (error) {
    if (method === "tools/call") {
      return result(id, {
        content: [{ type: "text", text: error.message || String(error) }],
        isError: true,
      });
    }
    return failure(id, -32603, error.message || String(error), {
      status: error.status || null,
      code: error.code || null,
    });
  }
}

function consume() {
  while (input.length) {
    const text = input.toString("utf8");
    if (/^Content-Length:/i.test(text)) {
      const headerEnd = text.indexOf("\r\n\r\n");
      if (headerEnd < 0) return;
      const match = text.slice(0, headerEnd).match(/Content-Length:\s*(\d+)/i);
      if (!match) { input = Buffer.alloc(0); return; }
      const length = Number(match[1]);
      const bodyStart = Buffer.byteLength(text.slice(0, headerEnd + 4), "utf8");
      if (input.length < bodyStart + length) return;
      const body = input.slice(bodyStart, bodyStart + length).toString("utf8");
      input = input.slice(bodyStart + length);
      try { handle(JSON.parse(body)); } catch {}
      continue;
    }
    const newline = input.indexOf(0x0a);
    if (newline < 0) return;
    const line = input.slice(0, newline).toString("utf8").trim();
    input = input.slice(newline + 1);
    if (!line) continue;
    try { handle(JSON.parse(line)); } catch {}
  }
}

process.stdin.on("data", (chunk) => { input = Buffer.concat([input, Buffer.from(chunk)]); consume(); });
process.stdin.on("error", () => process.exit(1));
process.on("uncaughtException", (error) => process.stderr.write(`[tasker-mcp] ${error.message}\n`));

