function expandFrontier() {
  markTilesDirty();
  const MAX_TERRAIN = 43;
  for (const [k, t] of G.tiles) {
    if (!t.revealed) continue;
    const [q, r] = hparse(k);
    for (const [nq, nr] of hnbr(q, r)) {
      const nk = hk(nq, nr);
      if (!G.tiles.has(nk)) {
        if (countTerrainTiles() < MAX_TERRAIN) {
          G.tiles.set(nk, {
            q: nq,
            r: nr,
            type: "face_down",
            revealed: false,
            pois: [],
          });
        }
      }
    }
  }
}

function revealAt(q, r) {
