  });
  // Public â€” IRIS threat (only when IRIS is in the game)
  if (withSynth)
    add(2, {
      text: "IRIS's last data upload is concerning. She appears to think the odds of survival would be higher with one fewer crew member. Keep an eye on her.",
      pub: true,
      irisCorruption: true,
    });
  // Private â€” resource
  add(4, {
    text: "A hidden cache â€” stowed deliberately, not by the crash. You pocket the contents before anyone else arrives.",
    pub: false,
    drawEq: true,
  });
  add(4, {
    text: "There's food here nobody logged. Take it. If anyone asks about your count, you found it in the field. That's true enough.",
    pub: false,
    gainFood: 1,
